package com.eidolon.sc.mobile;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;import java.time.*;import java.io.*;

/** Original upstream moments rules on the existing native model/persona pipeline. No images. */
final class SocialEngine {
 static volatile SocialEngine active;private volatile boolean stopped;private volatile ModelClient client;private String stage="prepare";private JSONObject requestConfig;private JSONArray preparationWarnings=new JSONArray();private String who="",id="",token="",target="";
 static void yieldFor(String who){SocialEngine e=active;if(e!=null&&e.who.equals(who))e.stop();}
 static void cancelComment(String id){SocialEngine own=active;if(own!=null&&own.target.equals(id))own.stop();}
 void stop(){stopped=true;ModelClient own=client;if(own!=null)own.cancel();}
 static boolean busy(ChatStore s,String who)throws Exception{return CallStore.busy(s,who)||SocialStore.count(s,"SELECT count(*) FROM pending_replies WHERE character=? AND status IN ('collecting','generating')",who)>0;}
 static void plan(Context c,ChatStore s,long now)throws Exception{synchronized(SocialStore.LOCK){JSONObject cfg=SocialStore.config(s);if(!cfg.getBoolean("enabled"))return;String day=SocialData.day(now);if(SocialStore.count(s,"SELECT count(*) FROM social_plans WHERE day=?",day)>0)return;long contact=SocialStore.contact(s);if(contact<=0||contact>now||now-contact>7*SocialData.DAY)return;JSONObject personal=s.personal(),profiles=PlacePool.profiles(c);boolean affinity=c.getSharedPreferences("settings",0).getBoolean("affinity",true);JSONArray chars=WritingEngine.characters(c);List<JSONObject> choices=new ArrayList<>();Random random=new Random(31L*day.hashCode()+contact/60000L);
  for(int i=0;i<chars.length();i++){JSONObject person=chars.getJSONObject(i);String who=person.getString("id");if(!SocialStore.hasTurn(s,who)||!SocialData.selected(cfg,who)||!SocialData.eligible(personal,who,affinity))continue;JSONObject profile=profiles.optJSONObject(who);boolean birthday=profile!=null&&birthday(profile.optString("birthday"),day);if(birthday||random.nextDouble()<SocialData.chance(personal,who,affinity))choices.add(person.put("socialBirthday",birthday));}
  Collections.shuffle(choices,random);choices.sort((a,b)->Boolean.compare(b.optBoolean("socialBirthday"),a.optBoolean("socialBirthday")));SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{ContentValues marker=new ContentValues();marker.put("day",day);marker.put("at",now);db.insertOrThrow("social_plans",null,marker);List<Long> times=new ArrayList<>();for(JSONObject person:choices){if(times.size()>=cfg.getInt("perDay"))break;String who=person.getString("id");if(SocialStore.count(s,"SELECT count(*) FROM social_posts WHERE character=? AND day=?",who,day)>0)continue;long due=0,lastWork=SocialWork.lastPlanned(c,s,who,now),afterWork=SocialWork.after(lastWork,now,random);if(afterWork>=SocialData.end(day))afterWork=0;for(int attempt=0;attempt<40;attempt++){long t=attempt==0&&afterWork>0?afterWork:SocialData.drawTime(day,now,random);boolean fits=t>0;for(long other:times)if(Math.abs(other-t)<SocialData.HOUR)fits=false;if(fits){due=t;break;}}if(due==0)continue;times.add(due);SocialStore.addTask(s,who,"post","",day,due,Math.min(SocialData.end(day)+2*SocialData.HOUR,due+2*SocialData.HOUR),new JSONObject().put("birthday",person.optBoolean("socialBirthday")).put("work",due==afterWork&&afterWork>0));}db.setTransactionSuccessful();}finally{db.endTransaction();}
 }}
 static boolean birthday(String md,String day){return md.equals(day.substring(5));}
 static String manual(Context c,ChatStore s,String who,long now)throws Exception{synchronized(SocialStore.LOCK){SocialStore.requireEnabled(s);WritingEngine.character(WritingEngine.characters(c),who);JSONObject cfg=SocialStore.config(s);if(!SocialData.selected(cfg,who)||!SocialStore.hasTurn(s,who)||!SocialData.eligible(s.personal(),who,c.getSharedPreferences("settings",0).getBoolean("affinity",true)))throw new IOException("请先与她完成聊天，并确认参与角色及当前关系状态");String day=SocialData.day(now);if(SocialStore.count(s,"SELECT count(*) FROM social_posts WHERE character=? AND day=?",who,day)>0)throw new IOException("她今天已经发过动态");if(SocialStore.used(s,SocialStore.budgetDay(s,now,false),"post")>=cfg.getInt("perDay"))throw new IOException("今日正文请求额度已用完，含失败及中断请求");if(SocialStore.count(s,"SELECT count(*) FROM social_tasks WHERE character=? AND kind='post' AND state='RUNNING'",who)>0)throw new IOException("她正在生成动态，请等待结果");SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{db.execSQL("UPDATE social_tasks SET state='CANCELLED',error='已改为手动安排' WHERE character=? AND kind='post' AND state='PENDING'",new Object[]{who});String id=SocialStore.addTask(s,who,"post","",day,now,now+2*SocialData.HOUR,new JSONObject().put("manual",true));db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}}
 void run(Context c)throws Exception{synchronized(SocialEngine.class){if(active!=null)return;active=this;}try(ChatStore s=new ChatStore(c)){long now=System.currentTimeMillis();SocialStore.cleanup(s,now);SocialStore.expire(s,now);plan(c,s,now);for(int n=0;n<5&&!stopped;n++){
   JSONObject cfg;JSONObject row;synchronized(SocialStore.LOCK){cfg=SocialStore.config(s);if(!cfg.getBoolean("enabled"))return;id=SocialStore.due(s,System.currentTimeMillis());if(id.isEmpty())return;row=SocialStore.task(s,id);who=row.getString("character");target=row.getString("target");if(busy(s,who)){s.getWritableDatabase().execSQL("UPDATE social_tasks SET due=?,error='等待该角色当前文字生成或通话完成，尚未调用模型' WHERE id=? AND state='PENDING'",new Object[]{System.currentTimeMillis()+60000,id});continue;}long current=System.currentTimeMillis();if(!SocialData.eligible(s.personal(),who,c.getSharedPreferences("settings",0).getBoolean("affinity",true))||!SocialData.selected(cfg,who)){skip(s,id,"当前关系或参与设置不适合发布",current);continue;}
    if(row.getString("kind").equals("post")){if(!row.getString("day").equals(SocialData.day(current))){skip(s,id,"已过计划日期，未补发",current);continue;}if(row.getJSONObject("body").optBoolean("work")){long lastWork=SocialWork.lastPlanned(c,s,who,current);if(lastWork>current){long deferred=SocialWork.after(lastWork,current,new Random());s.getWritableDatabase().execSQL("UPDATE social_tasks SET due=?,expires=? WHERE id=? AND state='PENDING'",new Object[]{deferred,deferred+2*SocialData.HOUR,id});continue;}}if(SocialStore.count(s,"SELECT count(*) FROM social_posts WHERE character=? AND day=?",who,row.getString("day"))>0){skip(s,id,"该角色当天已发布",current);continue;}long last=SocialStore.count(s,"SELECT coalesce(max(published),0) FROM social_posts");if(current-last<SocialData.HOUR){s.getWritableDatabase().execSQL("UPDATE social_tasks SET due=? WHERE id=? AND state='PENDING'",new Object[]{last+SocialData.HOUR+1,id});continue;}}
    else if(SocialStore.commentById(s,row.getString("target"))==null){skip(s,id,"评论已删除",current);continue;}
    String url=c.getSharedPreferences("settings",0).getString("url","").trim(),model=c.getSharedPreferences("settings",0).getString("model","").trim();if(url.isEmpty()||model.isEmpty()||!Vault.configured(c,"key"))return;
    token=SocialStore.claim(s,row,cfg,current,false);if(token.isEmpty()){skip(s,id,"今日请求额度已用完或任务已变化",current);continue;}
   }
   stage="prepare_assets";requestConfig=cfg;preparationWarnings=new JSONArray();try{if(row.getString("kind").equals("post"))generatePost(c,s,row,cfg);else generateReply(c,s,row,cfg);}catch(Exception e){synchronized(SocialStore.LOCK){SocialStore.finish(s,id,token,"FAILED",failure(s,e),System.currentTimeMillis());}}finally{client=null;}
  }}finally{synchronized(SocialEngine.class){if(active==this)active=null;}}
 }
 String failure(ChatStore s,Exception e)throws Exception{JSONObject detail=SocialFailure.classify(e,stopped,stage).put("warnings",preparationWarnings),row=SocialStore.task(s,id);if(row!=null&&row.optString("token").equals(token)){JSONObject body=row.getJSONObject("body").put("diagnostic",detail);android.content.ContentValues v=new android.content.ContentValues();v.put("body",body.toString());s.getWritableDatabase().update("social_tasks",v,"id=? AND token=?",new String[]{id,token});}return detail.getString("message");}
 static void skip(ChatStore s,String id,String reason,long now){s.getWritableDatabase().execSQL("UPDATE social_tasks SET state='SKIPPED',finished=?,error=? WHERE id=? AND state='PENDING'",new Object[]{now,reason,id});}
 String call(Context c,ChatStore sForRequest,JSONObject persona,JSONObject material,String instruction)throws Exception{if(stopped)throw new IOException("已取消");String url,key,model;synchronized(MediaContext.CONFIG_LOCK){SharedPreferences p=c.getSharedPreferences("settings",0);url=p.getString("url","");model=p.getString("model","");key=Vault.read(c);}ModelClient.endpointBase(url);client=new ModelClient();if(stopped){client.cancel();throw new IOException("已取消");}String system="沿用这位角色的既有人设、称呼与口吻：\n"+MediaData.cut(persona.optString("sheet"),10000)+"\n资料补充："+MediaData.cut(persona.optString("facts"),4000)+"\n"+instruction;stage="admission";synchronized(SocialStore.LOCK){SocialStore.reserveRequest(sForRequest,id,token,requestConfig,System.currentTimeMillis());}stage="request";String response=client.chat(url,key,ModelClient.request(model,system,Collections.emptyList(),material.toString()).put("max_tokens",2200),ignored->{});stage="parse";return response;}
 static JSONArray circle(Context c,JSONArray chars,JSONObject profiles,String who,boolean birthday,Random random)throws Exception{return SocialCircle.material(chars,profiles,who,birthday,System.currentTimeMillis(),random);}
 static JSONArray events(ChatStore s,String who,long now)throws Exception{return SocialWork.completed(s,who,now,false);}
 static String calendar(Context c,ChatStore s,String who)throws Exception{JSONObject personal=new JSONObject(s.personal().toString()),producer=personal.optJSONObject("producer");if(producer==null){producer=new JSONObject();personal.put("producer",producer);}producer.put("timeZone","Asia/Tokyo");return CalendarEvents.prompt(WritingEngine.asset(c,"calendar.json"),personal,who);}
 static final class Prepared {JSONObject persona,material;JSONArray places,events;Set<String> allowed,placeIds;JSONObject[] weather;boolean birthday;}
 JSONArray safeEvents(ChatStore s,long now)throws Exception{try{return events(s,who,now);}catch(JSONException optional){preparationWarnings.put("life_context_invalid");return new JSONArray();}}
 JSONArray safeRecent(ChatStore s,long now)throws Exception{try{return SocialStore.recent(s,who,now,5);}catch(JSONException optional){preparationWarnings.put("recent_post_invalid");return new JSONArray();}}
 String safeCalendar(Context c,ChatStore s)throws Exception{try{return calendar(c,s,who);}catch(JSONException|java.time.DateTimeException optional){preparationWarnings.put("calendar_context_invalid");return "";}}
 Prepared preparePost(Context c,ChatStore s,JSONObject row)throws Exception{long start=System.currentTimeMillis();Random random=new Random();JSONArray chars=WritingEngine.characters(c);JSONObject persona=WritingEngine.character(chars,who),profiles=PlacePool.profiles(c),profile=profiles.optJSONObject(who);boolean birthday=row.getJSONObject("body").optBoolean("birthday");stage="prepare_circle";JSONArray circle=circle(c,chars,profiles,who,birthday,random);Set<String> allowed=new HashSet<>();for(int i=0;i<circle.length();i++)allowed.add(circle.getJSONObject(i).getString("character"));stage="prepare_weather";JSONObject tokyoWeather=null;try{JSONObject weatherConfig=SocialStore.weatherConfig(s);if(weatherConfig.optBoolean("enabled")&&weatherConfig.optBoolean("tokyo",true))tokyoWeather=WeatherRuntime.cached(s,weatherConfig,null,true,start);}catch(JSONException optional){preparationWarnings.put("weather_cache_invalid");}JSONObject[] weather={tokyoWeather,null,null};stage="prepare_work";JSONArray workEvents=new JSONArray();if(row.getJSONObject("body").optBoolean("work"))try{workEvents=SocialWork.completed(s,who,start,true);}catch(JSONException optional){preparationWarnings.put("work_context_invalid");}boolean work=workEvents.length()>0;stage="prepare_places";JSONArray places=PlacePool.draw(PlacePool.all(c),who,work?null:profile==null?null:profile.optJSONArray("placeLikes"),SocialStore.usedPlaces(s,start),start,WeatherData.wet(weather[0]),work?SocialWork.categories(workEvents):null,PlacePool.venues(profile,start),random);Set<String> placeIds=new HashSet<>();for(int i=0;i<places.length();i++)placeIds.add(places.getJSONObject(i).getString("id"));stage="prepare_context";JSONArray events=work?workEvents:safeEvents(s,start),recent=safeRecent(s,start);JSONObject material=new JSONObject().put("author",who).put("tokyoTime",Instant.ofEpochMilli(start).atZone(SocialData.TOKYO).toString()).put("birthday",birthday).put("recordedVirtualEvents",events).put("kind",work?"work":"daily").put("calendar",safeCalendar(c,s)).put("publicAnniversaries",PlacePool.anniversaries(profile,start)).put("recentPosts",recent).put("circle",circle).put("places",places).put("weather",weather[0]==null?JSONObject.NULL:weather[0]);
  Prepared p=new Prepared();p.persona=persona;p.material=material;p.places=places;p.events=events;p.allowed=allowed;p.placeIds=placeIds;p.weather=weather;p.birthday=birthday;return p;
 }
 JSONObject diagnose(Context c,ChatStore s,String character)throws Exception{
  who=character;stage="prepare_assets";preparationWarnings=new JSONArray();try{Prepared p=preparePost(c,s,new JSONObject().put("body",new JSONObject()));return new JSONObject().put("ok",true).put("stage","prepared").put("requestAttempted",false).put("message","本地资料检查通过，未请求模型或天气服务，不占生成额度").put("warnings",preparationWarnings).put("circleCount",p.allowed.size()).put("placeCount",p.placeIds.size());}
  catch(Exception e){return SocialFailure.classify(e,false,stage).put("ok",false).put("warnings",preparationWarnings);}
 }
 void generatePost(Context c,ChatStore s,JSONObject row,JSONObject cfg)throws Exception{
  Prepared prepared=preparePost(c,s,row);JSONObject persona=prepared.persona,material=prepared.material;JSONArray places=prepared.places,events=prepared.events;Set<String> allowed=prepared.allowed,placeIds=prepared.placeIds;JSONObject[] weather=prepared.weather;boolean birthday=prepared.birthday;Random random=new Random();

  String instruction="你现在写自己的朋友圈，不是回复制作人的私聊。只写1至3句日语与对应简体中文字幕，像随手发近况，避免重复近期内容。已记录的virtual事件才可说成已完成；没有经历时可写日常感想或期待，不编造重大活动、约定或原作剧情，不暴露制作人私聊。publicAnniversaries是往年的公开演出资料，只可回忆当年，不得说成今天举办或自己现在到场；不为挂地点捏造到访。地点只能从places里选id或空字符串；在家/宿舍不挂真实地点，不捏造去过某店；天气只用所给快照。其他角色的公开互动只涉及这条动态与既有人际关系，圈子外的人不得出现。配图功能未开启，不要求或生成图片。只输出一个完整JSON对象，例如{\"ja\":\"日文纯台词\",\"zh\":\"中文纯台词\",\"placeId\":\"\",\"likes\":[],\"comments\":[]}。ja/zh为纯字符串，不包语言标签；comments项结构为{character:圈内id,ja,zh}。圈子为空时likes/comments留空。普通动态赞1至6人、评论0至3人；生日可最多10赞6评；不要把当前制作人画面或私密事实写进动态。";
  stage="admission";synchronized(SocialStore.LOCK){guard(c,s,row,cfg,System.currentTimeMillis());}JSONObject parsed=SocialData.post(call(c,s,persona,material,instruction),allowed,placeIds);if(stopped)throw new IOException("已停止");JSONObject place=null;for(int i=0;i<places.length();i++)if(places.getJSONObject(i).getString("id").equals(parsed.optString("placeId")))place=PlacePool.snapshot(places.getJSONObject(i));long now=System.currentTimeMillis();
  stage="commit";synchronized(SocialStore.LOCK){SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{guard(c,s,row,cfg,now);JSONObject post=new JSONObject().put("id",UUID.randomUUID().toString()).put("character",who).put("day",row.getString("day")).put("published",now).put("ja",parsed.getString("ja")).put("zh",parsed.getString("zh")).put("liked",false).put("place",place==null?JSONObject.NULL:place).put("weather",weather[0]==null?JSONObject.NULL:weather[0]).put("sources",events);
   ContentValues v=new ContentValues();v.put("id",post.getString("id"));v.put("character",who);v.put("day",post.getString("day"));v.put("published",now);v.put("body",post.toString());db.insertOrThrow("social_posts",null,v);JSONArray likes=parsed.getJSONArray("likes"),comments=parsed.getJSONArray("comments");for(int i=0;i<Math.min(likes.length(),birthday?10:6);i++)saveCircle(db,post.getString("id"),new JSONObject().put("character",likes.getString(i)).put("kind","like"),now+(5+random.nextInt(176))*60000L);long shown=now;for(int i=0;i<Math.min(comments.length(),birthday?6:3);i++){shown=Math.max(shown+60000,now+(15+random.nextInt(346))*60000L);saveCircle(db,post.getString("id"),comments.getJSONObject(i).put("kind","comment"),shown);}SocialStore.finish(s,id,token,"PUBLISHED","",now);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 }
 static void saveCircle(SQLiteDatabase db,String post,JSONObject body,long shown)throws Exception{String id=UUID.randomUUID().toString();body.put("id",id).put("post",post).put("shown",shown);ContentValues v=new ContentValues();v.put("id",id);v.put("post",post);v.put("shown",shown);v.put("body",body.toString());db.insertOrThrow("social_circle",null,v);}
 void guard(Context c,ChatStore s,JSONObject task,JSONObject cfg,long now)throws Exception{
  JSONObject current=SocialStore.task(s,id),settings=SocialStore.config(s);
  if(stopped)throw new SocialFailure.State("cancelled","任务已主动取消");
  if(now>=task.getLong("expires")||task.getString("kind").equals("post")&&!task.getString("day").equals(SocialData.day(now)))throw new SocialFailure.State("expired","任务已过有效期或计划日期");
  if(current==null||!current.optString("state").equals("RUNNING")||!current.optString("token").equals(token))throw new SocialFailure.State("invalidated","请求身份已失效，可能已删除或恢复数据");
  if(!settings.getBoolean("enabled")||settings.getLong("revision")!=cfg.getLong("revision"))throw new SocialFailure.State("configuration_changed","朋友圈已关闭或配置已改变");
  if(!SocialData.eligible(s.personal(),who,c.getSharedPreferences("settings",0).getBoolean("affinity",true)))throw new SocialFailure.State("eligibility","角色当前关系状态不适合发布");
 }
 void generateReply(Context c,ChatStore s,JSONObject row,JSONObject cfg)throws Exception{JSONObject comment=SocialStore.commentById(s,row.getString("target"));if(comment==null)throw new IOException("评论已删除");JSONObject post=SocialStore.shown(s,SocialStore.post(s,comment.getString("post")),System.currentTimeMillis()),persona=WritingEngine.character(WritingEngine.characters(c),who);JSONObject material=new JSONObject().put("post",post).put("producerComment",comment.getString("text")).put("relationship",PersonalData.tier(c.getSharedPreferences("settings",0).getBoolean("affinity",true)?(int)SocialData.score(s.personal(),who):50));
  synchronized(SocialStore.LOCK){guard(c,s,row,cfg,System.currentTimeMillis());}JSONObject reply=SocialData.pair(SocialData.object(call(c,s,persona,material,"你现在只回复制作人在你的朋友圈下的这条评论。沿用人设、称呼和既有关系，1至2句，轻松自然，不扩写动态之外未给定的事实，不把赞评当好感奖励，不要求对方继续互动。仅输出一个完整JSON对象，例如{\"ja\":\"日文纯台词\",\"zh\":\"中文纯台词\"}，字段内不包语言标签，不是聊天回合，不调用图片功能。称呼参考仅用于本条回复，不向其他角色披露档案："+ProducerProfile.prompt(s.personal()))));long now=System.currentTimeMillis();stage="commit";synchronized(SocialStore.LOCK){SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{guard(c,s,row,cfg,now);JSONObject actual=SocialStore.commentById(s,row.getString("target"));if(actual==null||!actual.getString("text").equals(comment.getString("text")))throw new IOException("原评论已改变");actual.put("reply",reply).put("replyAt",now);ContentValues v=new ContentValues();v.put("body",actual.toString());db.update("social_comments",v,"id=?",new String[]{actual.getString("id")});SocialStore.finish(s,id,token,"PUBLISHED","",now);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 }
}
